%% MATLAB Validation Script
% Reads datasets generated by Python, runs the KSG estimator,
% and saves results so they can be compared against Python estimates.
%
% Run this script from the root of the ksg-estimator project.

%% Setup
% Add the matlab folder to the path so miKnn.m is accessible
% We use the full path relative to the script's own location
% so it works regardless of where MATLAB is called from
script_dir = fileparts(mfilename('fullpath'));
project_root = fileparts(script_dir);
addpath(script_dir);
cd(project_root);

% Set estimator options to match Python defaults
options.K = 2;
options.p = inf;  % L-infinity norm, matches 'chebyshev' in Python
options.EmbeddedShuffleTest = false;

% Create output folder for results
results_dir = 'datasets/results/matlab/';
if ~exist(results_dir, 'dir')
    mkdir(results_dir);
end

%% List of datasets to validate
datasets = {
    'datasets/data/independent_uniform_n1000.csv', ...
    'datasets/data/gaussian_rho00_n1000.csv',      ...
    'datasets/data/gaussian_rho05_n1000.csv',      ...
    'datasets/data/gaussian_rho09_n1000.csv'       ...
};

%% Run estimator on each dataset
for i = 1:length(datasets)
    filepath = datasets{i};
    
    % Read the CSV file (skip the header row)
    data = readmatrix(filepath);
    
    % Split into x and y columns
    x = data(:, 1);
    y = data(:, 2);
    
    % Run the KSG estimator
    I = MIKnn(x, y, options);
    
    % Print result to console
    fprintf('Dataset: %s\n', filepath);
    fprintf('Estimated MI: %.6f nats\n\n', I);
    
    % Save result to a text file
    % Build output filename from input filename
    [~, name, ~] = fileparts(filepath);
    result_file = fullfile(results_dir, [name, '_matlab_result.txt']);
    fid = fopen(result_file, 'w');
    fprintf(fid, '%.18e\n', I);
    fclose(fid);
end

fprintf('All results saved to %s\n', results_dir);